/// <summary>
/// The <c>WHSWorkUserDbt_Extension</c> represents a extension of WHSWorkUser.
/// </summary>
[
    ExtensionOf(tableStr(WHSWorkUser))
]
final class AVAWHSWorkUserDbt_Extension
{
}

Method.Source:
/// <summary>
/// CoC of insert
/// </summary>
public void insert()
{
    next insert();

    if (this.AVAUserDefaultPrinterCode
     && !AVAWHSWorkUserPrinter::exist(this.UserId, this.AVAUserDefaultPrinterCode))
    {
        this.avaCreateWHSWorkUserPrinter();
    }
}

public void update()
{
    AVAPrinterCode prevPrinterCode;

    prevPrinterCode = this.orig().AVAUserDefaultPrinterCode;

    next update();

    if (this.AVAUserDefaultPrinterCode
     && this.AVAUserDefaultPrinterCode != prevPrinterCode
     && !AVAWHSWorkUserPrinter::exist(this.UserId, this.AVAUserDefaultPrinterCode))
    {
        this.avaCreateWHSWorkUserPrinter();
    }
}

private void avaCreateWHSWorkUserPrinter()
{
    AVAWHSWorkUserPrinter   avaWHSWorkUserPrinter;

    ttsbegin;
    avaWHSWorkUserPrinter.initValue();
    avaWHSWorkUserPrinter.UserId        = this.UserId;
    avaWHSWorkUserPrinter.PrinterCode   = this.AVAUserDefaultPrinterCode;
    avaWHSWorkUserPrinter.insert();
    ttscommit;

}
